class FreqStack {
    private final Map<Integer,Integer> frequency=new HashMap<>();
    private final Map<Integer,Deque<Integer>> groups=new HashMap<>();
    private int maximum;
    public FreqStack(){
    }
    public void push(int val){
        int count=frequency.merge(val,1,Integer::sum);
        maximum=Math.max(maximum,count);
        groups.computeIfAbsent(count,key->new ArrayDeque<>()).push(val);
    }
    public int pop(){
        Deque<Integer> stack=groups.get(maximum);
        int value=stack.pop();
        frequency.put(value,frequency.get(value)-1);
        if(stack.isEmpty())maximum--;
        return value;
    }
}

code.kotlin:
class FreqStack {
    private val frequency=mutableMapOf<Int,Int>();
    private val groups=mutableMapOf<Int,java.util.ArrayDeque<Int>>();
    private var maximum=0;
    fun push(value:Int){
        val count=(frequency[value]?:0)+1;
        frequency[value]=count;
        maximum=maxOf(maximum,count);
        groups.getOrPut(count){
            java.util.ArrayDeque()
        }.push(value)
    };
    fun pop():Int{
        val stack=groups[maximum]!!;
        val value=stack.pop();
        frequency[value]=frequency[value]!!-1;
        if(stack.isEmpty())maximum--;
        return value
    }
}

